          VartaPrasang(
            number: 5,
            paragraphs: [
              'गं गोपकिरनुवनं नयतोरुदारवेणुस्वनै: कलपदैस्तनुभूत्सुसख्य:। अस्पंदनं गतिमता पुलकस्तरुणा नियोगपाशकुतलक्षणयोर्विचीतत्र ॥',
              'આ શ્લોક નું વ્યાખ્યાન શ્રી ગુંસાઈજી ગોવિંદસ્વામી આગળ કરવા લાગ્યા. કહેતા કહેતા જયારે અડધી રાત પસાર થઈ ત્યારે શ્રી ગુંસાઈજી પોઢ્યા. ગોવિંદસ્વામી ઘરે ગયા, તે વખતે શ્રી બાલકૃષ્ણજી, શ્રી ગોકુલનાથજી તથા શ્રી રઘુનાથજી ત્રણ ભાઈ વૈષ્ણવના મંડળમાં બિરાજતા હતા. ગોવિંદસ્વામીએ જઈને દંડવત કર્યા. ત્યારે શ્રી ગોકુલનાથજી એ પૂછ્યું કે શ્રી ગુંસાઈજીની પાસે કયો પ્રસંગ ચાલતો હતો. ત્યારે ગોવિંદસ્વામીએ એ શ્લોક નો શ્રી સુબોધિનીજીનો પ્રસંગ કહ્યો. ફરીથી કહ્યું આપનું વ્યાખ્યાન આપ કરે તેમાં શું કહેવા જેવું હોય? જેના વેદ પણ જણતા નથી તેનું વ્યાખ્યાન તો આપ કરે તોજ થાય, જયારે આ પ્રમાણે કહ્યું ત્યારે શ્રી ગોકુલનાથજી એ બન્ને ભાઈઓને કહ્યું કે ગોવિંદસ્વામીએ શ્રી ગુંસાઈજીના સ્વરૂપને શી રીતે જણ્યું? તેના ઉપર આપે કેવી કૃપા કરી છે! તેના ભાગ્યનું શું વર્ણન કરીએ! આ કહીને શ્રી ગોકુલનાથજી ચૂપ થઈ ગયા.',
            ],
          ),
          VartaPrasang(
            number: 6,
            paragraphs: [
              'આ ગોવિંદસ્વામી શ્રીનાથજીની સાથે ખેલતા હતા. એક દિવસે અપ્સરા કુંડ થઈને તથા ગોવર્ધન પર્વત ઉપર થઈને શ્રી ગોવર્ધન નાથજીની સંગ ગોવિંદદાસ આવતા હતા. તેમણે ત્યાંથી રાજભોગની આરતીનો અવાજ સાંભળ્યો, ત્યારે ગોવિંદસ્વામી એ કહ્યું " શ્રી નાથજી તો હમણાં આવે છે. રાજભોગ કોણ આરોગે છે? ગોવિંદસ્વામીએ જઈને શ્રી ગુંસાઈજીને વિનંતી કરી ત્યારે શ્રી ગુંસાઈજીએ બીજો રાજભોગ સિદ્ધ કરીને ધરાવ્યો.',
              'ગોપાળદાસ ભીતરિઆએ શ્રી ગુંસાઈજીને વિનંતી કરી. કે "એક દિવસ પૂછરીપર થઈને ગોવિંદદાસને શ્રીનાથજી ની સંગે આવતા મેં જોયા હતા." ત્યારે શ્રી ગુંસાઈજીએ કહ્યું "કુંભનદાસ, ગોવિંદસ્વામી તથા ગોપીનાથદાસ ગ્વાલ એ ત્રણે શ્રીનાથજીના એકાંતના સખા છે. તેથી શ્રી મહાપ્રભુજીએ તેમને અધિકાર આપ્યો છે. આ વાત સાંભળી ને ગોપાલ દાસજી બહુજ પ્રસંન્ન થયા અને પોતાના મનમાં કહેવા લાગ્યા, જો હું ભીતરીઓ થયો તેથી શું થયું? એ ગોવિંદસ્વામી એવા કૃપાપાત્ર હતા.',
            ],
          ),
          VartaPrasang(
            number: 7,
            paragraphs: [
              'એક દિવસ ગોવિંદસ્વામી ઉત્થાપનના સમયે શ્રીનાથજીના દર્શન માટે ગયા. ત્યારે જોયું તો માલુમ પડ્યું કે શ્રીનાથજીની પાઘડી નો પેચ ખુલ્લો રહી ગયો હતો, ત્યારે ગોવિંદસ્વામીએ કહ્યું " પાઘડીનો પેચ શા માટે ખુલ્લો રહ્યો છે"? શ્રીનાથજી એ કહ્યું " તું પાઘડીનો પેચસમો કર" તેથી ગોવિંદસ્વામીએ અંદર જઈને પાઘડીનો પેચસમો કર્યો। ત્યારે ભીતરીઆએ શ્રી ગુંસાઈજીને કહ્યું "ગોવિંદદાસે અપરસ છુવાઈ નાખી છે. ત્યારે શ્રી ગુંસાઈજીએ આજ્ઞા કરી કે ગોવિંદદાસથી શ્રીનાથજી છુવાતા નથી એતો શ્રીનાથજીની સાથે હંમેશા ખેલે છે. એ ગોવિંદસ્વામી એવા કૃપાપાત્ર હતાં.',
            ],
          ),
          VartaPrasang(
            number: 8,
            paragraphs: [
              'એક દિવસે શ્રી ગુંસાઈજી શ્રીનાથજી નો શૃંગાર કરતા હતા. ત્યારે ગોવિંદસ્વામી જગનમોહનના કીર્તન કરતા હતા. ત્યારે શ્રીનાથજી એ ગોવિંદદાસને આંઠ કાંકરી મારી. પછી ગોવિંદસ્વામી એ એક કાંકરી મારી. તેથી શ્રીનાથજી ચમકી ઉઠ્યા. ત્યારે શ્રી ગુંસાઈજીએ કહ્યું "અરે ગોવિંદદાસ આ શું કર્યું?" ગોવિંદસ્વામી એ કહ્યું " અરે મહારાજ!તમારો તો પુત્ર અને બીજા તો વેચાણ. આઠ વખત મને કાંકરી મારી ત્યારે આપ કશું બોલ્યા નહીં," આ સાંભળીને શ્રી ગુંસાઈજી ચૂપ થઈ ગયા. આ ગોવિંદદાસને એવો સખા ભાવ સિદ્ધ થયો હતો.',
            ],
          ),
          VartaPrasang(
            number: 9,
            paragraphs: [
              'એક દિવસ ગોવિંદદાસની દીકરી દેશમાંથી આવી. પરંતુ કોઈ દિવસ ગોવિંદસ્વામી તેની સાથે બોલતા નહીં, ત્યારે કાન્હબાઈએ કહ્યું કે દીકરી ની સાથે એક દિવસ તો બોલો. ત્યારે તેમણે કહ્યું મનતો એકજ છે. આમાં લગાવું કે એનામાં(દીકરીમાં)લગાઉં. પછી થોડા દિવસ રહીને દીકરી દેશ જવા લાગી. ત્યારે શ્રી વહુ બેટીજીએ સાડી તથા ચોળી મોકલી. ત્યારે ગોવિંદસ્વામીના મનમાં દયા આવી જો ગુરૂ ના ઘરની અણપ્રસાદી લેતો તેનો બગાડ થાય. ગોવિંદસ્વામી દીકરી સાથે કોઈપણ દિવસ બોલતા ન હતા તો પણ દયાને લીધે બોલ્યા કે "જો તું આ લઈશ તો તારૂ બુરૂ થશે" ત્યારે દીકરીએ કહ્યું " મને અત્યાર સુધી કશી સમજણ નહોતી તમે મારા ઉપર ઘણી કૃપા કરીને રસ્તો દેખાડ્યો. પછી એ બધા કપડાં પાછાં મોકલ્યાં. દીકરી પોતાને ઘરે ગઈ. આ ગોવિંદસ્વામી ગુરૂ અંશથી એવા બીતા હતા.',
            ],
          ),
          VartaPrasang(
            number: 10,
            paragraphs: [
              'એક વખત ફાગણના દિવસ હતા, તેથી સેનભોગ સરાવીને શ્રી ગુંસાઈજી બીડી આરોગાવતા હતા, ત્યારે ગોવિંદસ્વામી ધમાર ગાતા હતા. તે ધમાર " શ્રી ગોવર્ધનરાયલાલ" પુરી કર્યા વગર ગોવિંદસ્વામી ચૂપ થઈ ગયા. ત્યારે શ્રી ગોવિંદદાસે કહ્યું "મહારાજ આ ધમાર તો અટકી ગઈ છે. એ તો ઘરમાં જઈને ઘૂસી ગયો છે. ખેલતો બંધ પડ્યો છે. હવે હું શું ગાઉ? તે સાંભળી ને શ્રી ગુંસાઈજી ચૂપ થઈ ગયા. પછી બેઠક માં પધાર્યા અને એક તુક બનાવીને ગોવિંદસ્વામીના નામની એ ધમારમાં ધરી. તે દિવસથી ગોવિંદસ્વામીની ધમાર સાડાબાર કહેવાય છે. એ ગોવિંદસ્વામી એવા કૃપાપાત્ર હતા, લીલાનાં દર્શન કરીને તે ગાન કરતા હતા.',
            ],
          ),
          VartaPrasang(
            number: 11,
            paragraphs: [
              'આ ગોવિંદ સ્વામી મહાવનના ટેકરા ઉપર નિત્ય ગાન કરતા હતા, શ્રીનાથજી નિત્ય સાંભળવાને આવતા હતા. વળી શ્રીનાથજીની સાથે ગાન કરતા હતા, આ ગોવિંદ સ્વામી અષ્ટસખાંમાંના એક હતા. કોઈ વખત શ્રીનાથજીની ચૂક પડતી ગોવિંદસ્વામી ભૂલ કાઢતા હતા. શ્રીનાથજી અને ગોવિંદસ્વામીના ગાન સાંભળવાને માટે શ્રી ગોકુલનાથજી નિત્ય પધારતા હતા અને એક મનુષ્યને બેસાડી રાખતા કે જેથી જયારે શ્રીગુંસાઈજી ભોજન કરવા પધારે ત્યારે તેમને બોલાવે. એક દિવસ આ માણસના મનમાં એવું થયું કે શ્રી ગોકુલનાથજી હમેશાં શ્રી ગુસાંઈજીથી છાના પધારે છે. એક દિવસ જો હું ન બોલાવું તો શ્રી ગુંસાઈજી સર્વ વાત જાણી જશે. તેથી શ્રી ગોકુલનાથજીનું નિત્ય જવાનું બંધ થઈ જશે. એમ સમજીને આ માણસ એક દિવસ બોલાવા ન ગયો. જયારે શ્રીગુંસાઈજી ભોજન માટે પધારવા લાગ્યા. ત્યારે બધા લાલજી આવ્યા. શ્રી ગોકુલનાથજી ન આવ્યા. ત્યારે શ્રી ગુંસાઈજીએ બીજા માણસને આજ્ઞા કરી કે ગોવિંદસ્વામીની પાસે વલ્લભજી બેઠા છે. તેમને બોલાવી લાવો. જયારે બીજો માણસ બોલાવી લાવ્યો, ત્યારે જે માણસ જાણી જોઈને બોલાવા ન હોતો ગયો તેને પશ્ચાતાપ થયો. "અરેરે શ્રીગુંસાઈજી તો સર્વે જાણે છે. મેં શા માટે શ્રી ગોકુલનાથજી તરફ કુટિલતા કરી એવો પશ્ચાતાપ થયો. એ ગોવિંદસ્વામી એવા કૃપાપાત્ર હતા, કે તેમની સાથે શ્રીનાથજી ક્ષણે ક્ષણે આવીને બિરાજતાં.',
            ],
          ),
          VartaPrasang(
            number: 12,
            paragraphs: [
              'આ ગોવિંદસ્વામી પાઘડી સુંદર બાંધતા હતા. પાઘડીમાં કકડા હોય તોપણ એવી રીતે બાંધતા કે કોઈને ખબર પડતી નહીં. એક દિવસે એક વ્રજવાસી ગોવિંદસ્વામી ની પાઘડી સુંદર જાણીને ઉતારી લીધી. ત્યારે ગોવિંદસ્વામી કહ્યું " આ કકડા સાંભળીને રાખજો કાલે તારે ઘેર આવીને હું લઈ જઈશ" આ વ્રજ વાસીએ પગે લાગીને પાઘડી પછી આપી દીધી. આ ગોવિંદદાસ ની પાઘડી બાંધવામાં એવી ચતુરાઈ હતી.',
            ],
          ),
          VartaPrasang(
            number: 13,
            paragraphs: [
              'આ ગોવિંદદાસ નિત્ય જસોદા ઘાટ પર જઈને બેસતાં. અહીંઆ એક દિવસ એક વૈરાગી ગાવા લાગ્યો તે ગાન રાગને તાલ વગરનું હતું ત્યારે ગોવિંદસ્વામી એ કહ્યું " તુ ગાઈશ નહીં આવા ગાનથી શું? " વૈરાગી એ કહ્યું " હું રામને પ્રસન્ન કરું છું " ત્યારે ગોવિંદસ્વામી એ કહ્યું રામ તો ચતુર શિરોમણી છે. આમતે કેવી રીતે પ્રસન્ન થાય? જો તારો સાચો ભાવ હોય તો મનમાં નામ લે તો પ્રસન્ન થાય" આ ગોવિંદસ્વામી એવા નિઃશંક હતા.',
            ],
          ),
          VartaPrasang(
            number: 14,
            paragraphs: [
              'એક દિવસ શ્રીનાથજી શ્યામઢાંક ઉપર ચઢી ને બિરાજતા હતા અને મુરલી બજાવતા હતા. ગોવિંદદાસ દૂરથી ટેકરા ઉપર બેસીને જોતા. આ વખતે શ્રી ગુંસાઈજી સ્નાન કરીને ઉત્થાપન કરવાને માટે શ્રી ગિરિરાજ ઉપર પધાર્યા. શ્રીનાથજીએ શ્યામઢાંક પરથી તેમને દીઠા એટલે ઉતાવળથી કુદ્યા તેથી વાંધો ફાટ્યો અને તેનું ચિંદરડું ઝાડ ઉપર રહી ગયું. શ્રી ગુંસાઈજીએ કમાડ ખુલ્લાં કર્યા અને ઉત્થાપન કરાવ્યાં જુએ છે તો વાંધો ફાટી ગયો. પછી માણસોને પૂછ્યું " અહીં કોઈ આવ્યું તો નહોતું? ત્યારે બધાએ ના કહી. પછી થી આપ વિચાર કરવા લાગ્યા ત્યારે ગોવિંદદાસે કહ્યું આપ આ વાતમાં વિચાર શો કરો છો? પુત્રનો સ્વભાવ જાણતા નથી. એ બહુ ચંચળ છે. શ્યામઢાંક ઉપરથી કૂદીને વાઘા ને ફાડી નાંખ્યો છે. આપ આવો તો દેખાડું કે ચીંદરડું લટકી રહ્યું છે પછીથી શ્રી ગુંસાઈજી પધારીને તે ચીંદરડું ઉતરાવી લાવ્યા. શ્રી ગુંસાઈજીએ શ્રીનાથજી ને પૂછ્યું " આપે ઉતાવળ શાથી કરી " ત્યારે શ્રીનાથજી એ કહ્યું " ઉત્થાપન નો સમય થયો હતો તેથી. વળી આપ ન્હાઈ ને પધાર્યા હતાં. તેથી ઉતાવળ થઈ તે દિવસથી એવો બંદોબસ્ત કર્યો કે ત્રણવાર ઘંટનાદ તથા ત્રણવાર શંખનાદ કરી અને વિસ પળ રહીને મંદિરના કમાડ ખોલીને ઉત્થાપન કરાવવાં. એ ગોવિંદદાસ એવા કૃપાપાત્ર ભગવદીય હતા.',
            ],
          ),
          VartaPrasang(
            number: 15,
            paragraphs: [
              'એક દિવસે આગ્રામાં અકબર બાદશાહે સાંભળ્યું કે ગોવિંદસ્વામી બહુ જ સુંદર ગાય છે વળી તેમને કોઈની અપેક્ષપણ નથી તેમ નિઃશંક છે તો એમના મુખનો રાગ કેવી રીતે સંભળાય? આ વિચાર કરીને બાદશાહ વેશ બદલીને એકલો શ્રી ગોકુળમાં આવ્યો. આ વખતે ગોવિંદદાસ જશોદા ઘાટ પર બેસી ને ભૈરવ રાગ ગાતા હતા.ત્યારે બાદશાહે "વાહ વાહ" કહ્યું. એટલે ગોવિંદસ્વામી એ કહ્યું " આ રાગ છુંવાઈ ગયો" આ સાંભળીને તેણે કહ્યું" હું અકબર બાદશાહ છું." ત્યારે તેમણે કહ્યું " જો તમે બાદશાહ હો તો તમારી બાદશાહી કરો, પણ આ રાગ તો તમારા સાભળવાથી છુવાઈ ગયો." ત્યારે બાદશાહે વિચાર કર્યો કે હું એક દેશ નો રાજા છું જયારે આને તો ત્રણ લોકો નો વૈભવ પણ ફીકો લાગે છે તો શી રીતે આપણા હુકમ માં રહે? એમ વિચાર કરી બાદશાહ જતો રહ્યો અને ગોવિંદસ્વામી તે દિવસ થી ભૈરવ રાગ ગયો નહિ. આ ગોવિંદસ્વામી એવા ટેકી ભગવદીય હતા.',
            ],
          ),
          VartaPrasang(
            number: 16,
            paragraphs: [
              'ગોવિંદસ્વામીની સાથે શ્રીનાથજી હંમેશા વનમાં ખેલતા કોઈ વખત ગોવિંદસ્વામીને ઘોડો બનાવે અગર કોઈ દિવસ હાથી બનાવે. આ પ્રમાણે હંમેશા ક્રીડા કરતા. એક દિવસ શ્રીનાથજી એ ગોવિંદસ્વામીને ઘોડો બનાવ્યો અને પોતે ઉપર અસ્વાર થયા તે વખતે ગોવિંદસ્વામી એ ઘોડાની માફક લઘુશંકા કરી આ વાત એક વૈષ્ણવે જોઈ તેણે જઈને શ્રીગુંસાઈજીને કહ્યું જો ગોવિંદસ્વામી હાથી, ઘોડા થાય તો તે હાથી, ઘોડાનો વેષ પૂરો ન કરે તો કેમ બને? આ વાતમાં તમારે પડવું નહીં. આ વાતમાં તમારે પડવું નહીં. આ વાત સાંભળીને તે વૈષ્ણવ ચૂપ થઈ ગયો. એ ગોવિંદસ્વામી એવા કૃપા પાત્ર હતા.',
            ],
          ),
          VartaPrasang(
            number: 17,
            paragraphs: [
              'એક દિવસ ગોવિંદદાસ શ્રી ગુસાંઇજીની સાથે મથુરાજીમાં કેશવરાયજીના દર્શન કરવાને ગયા. તે વખતે ઉન્હાળો હતો. સર્વ જરીના વાઘા અને જરીની ઓઢણી જોઈને ગોવિંદદાસે કેશવરાયને પૂછ્યું "કેમ ઠીક છે ને?" તે સાંભળી કેશવરાયજી હસ્યાં. ત્યારે શ્રીગુંસાઈજીએ કહ્યું "અરે ગોવિંદદાસ એવું ન બોલો." ત્યારે ગોવિંદદાસે કહ્યું મહારાજ માંદા માણસનો પોષાક પહેર્યો છે તો શા માટે ન પુછાય?" આ વાત સાંભળીને શ્રી ગુંસાઈજી ચૂપ રહ્યાં.',
            ],
          ),
          VartaPrasang(
            number: 18,
            paragraphs: [
              'એક દિવસ શ્રીનાથજીનો રાજભોગ આવતો હતો, ત્યારે ભીતરીયાને ગોવિંદસ્વામીએ કહ્યું કે રાજભોગ ધર્યો પહેલાં મને પ્રસાદ લેવડાવો, ત્યારે ભીતરીઆએ થાળ ફેંકી દીધો અને શ્રીગુસાંઇજીને બોલાવ્યા. શ્રીગુંસાઈજીએ ગોવિંદદાસને પૂછ્યું "આ શું? " ત્યારે ગોવિંદસ્વામીએ કહ્યું કે આપ પોતાની સાથે મને ખેલવા લઈ જાય છે. જો પ્રસાદ લેવાને હું પાછળ રહી જાઉં તો વનમાં પછીથી મને શ્રીનાથજી ના મળે, તો હું શું કરૂ. તે સાંભળીને શ્રીગુંસાઈજીએ એવો બંદોબસ્ત કર્યો કે રાજભોગ આવવાને વખતે ગોવિંદદાસને પ્રસાદ લેવડાવવો એવી ભંડારીને આજ્ઞા આપી. એ ગોવિંદસ્વામી એવા કૃપાપાત્ર હતા. જેમના વગર શ્રીનાથજી રહી શકતા નહોતા.',
            ],
          ),
          VartaPrasang(
            number: 19,
            paragraphs: [
              'એક દિવસ શ્રીનાથજી ગોવિંદસ્વામી સાથે ખેલતા હતા. જયારે શ્રીનાથજીનો દાવ આવ્યો, ત્યારે ઉત્થાપનનો વખત થયો હતો. શ્રીનાથજી નાશીને મંદિરમાં પેસી ગયા. તેથી મંદિરની અંદર જઈને શ્રીનાથજીને ગીલ્લી મારી, એટલે ટહેલ કરનારા સેવકોએ ગોવિંદસ્વામીને ધક્કો માર્યો અને બહાર કાઢ્યા. પછી ઉત્થાપન ભોગ ધર્યો. તેથી ગોવિંદસ્વામી જઈને રસ્તામાં બેઠા અને કહ્યું કે હમણાં ગાયની સાથે શ્રીનાથજી આ રસ્તા ઉપર આવશે, તે વખતે હું એમને માર મારીશ. પછીથી શ્રીગુંસાઈજી સ્નાન કરીને મંદિરમાં પધાર્યા અને જોયું તો શ્રીનાથજી રિસમાં હતા. ઉત્થાપનની સામગ્રી આરોગતા નહોતાં. ત્યારે શ્રીગુંસાઈજી એ શ્રીનાથજીને પૂછ્યું "આજ કેમ છે? ત્યારે શ્રીનાથજી એ કહ્યું જ્યાં સુધી ગોવિંદદાસને મનાવશો નહીં ત્યાં સુધી મને કશું પણ ભાવવાનું નથી. કારણકે મારે એ રસ્તે ગયા વગર તથા તેની સાથે રમ્યા વગર ચાલવાનું નથી. જો રસ્તા માં જઉં તો એ મને મારે એ ચિંતાથી મને કશું ભાવતું નથી. ગોવિંદદાસ આવશે ત્યારે કંઈક ભાવશે. એ વાત સાંભળીને અને શ્રીનાથજી ની ભક્તવત્સલતા જોઈને શ્રીગુંસાઈજીનું હૃદય ભરાઈ આવ્યું. પછીથી ગોવિંદદાસ ને બોલાવીને અને મનાવીને શ્રીનાથજીને વિનંતી કરી કે આ હાજર છે. હવે આવ્યા છે" ત્યારે શ્રીનાથજી આરોગ્યા. આ ગોવિંદદાસ એવા કૃપાપાત્ર ભગવદીય હતા. તેમની વાર્તા અનિર્વચનીય છે.',
            ],
          ),
        ],
        saar: [
          'આ જગતમાં જીવ જે વસ્તુને શોધે છે તે તેને મળે છે શ્રી ઠાકોરજી સવત્ર બિરાજે છે, તેમને જો કોઈ શોધે તો શા માટે ન મળે? પણ જીવની વાસના સંસારી પદાર્થમાં છે. પણ આ સંસારી દ્રષ્ટિનો ત્યાગ કરીને અલૌકિક દ્રષ્ટિથી પ્રભુ સન્મુખ થઈને શોધ કરે તો પ્રભુ મલેને મલેજ.',
          'ભક્તિ માર્ગમાં દ્રષ્ટિથી ધગસ તથા આતુરતા એ મુખ્ય વસ્તુ છે. આ માર્ગમાં સાધનની અપેક્ષા નથી. સાધનો તો સગુણ ભક્તિ ને માટે અપેક્ષિત હોય છે. પણ અહીંયા તો નિર્ગુણ ભક્તિ હોય છે. निस्त्रैगुण्ये पथि विचरतां को निषेध: ત્રિગુણાતીત આ માર્ગમાં વિધિ શું અને નિષેધ શું? ભાવાર્થ કે આ માર્ગમાં વિધિ નિષેધ કોઈ છેજ નહીં. માત્ર હૃદયની અતુરતાથી-ભાવથી ભક્તિ થાય તો તે ભક્તિ નું ફળ મળે છે.',
          'ભક્તિનું ફળ ભક્તિજ છે. સાધન રૂપ ભક્તિ થી સાધ્ય રૂપ ભક્તિ પ્રાપ્ત કરાય છે. સેવાનું ફળ સેવા છે. તે ત્રણ પ્રકારની છે. તનુજા,વિત્તજા,અને માનસિક,તેમાં માનસિક ઉત્તમ છે. ફક્ત શ્રીજીના પરમ કૃપાપાત્ર ભગવદીઓને એ થઈ આવે છે. અધિકારી પરત્વે જીવથી સેવા થઈ શકે છે.',
          'ભગવદીય ના સત્સંગથી અન્યનો પણ ઉદ્ધાર થાય છે અને ભગવત્પ્રાપ્ર્તિ થાય છે (જુઓ પ્રસંગ 3 જો)',
          'ભક્તિમાર્ગ ફૂલનું વૃક્ષ છે અને કર્મમાર્ગ કાંટાની વાડ જેવો છે. જેને એ પુષ્પની સૌરભ લેવી છે, તેતો કાંટાની વાડ આગળ થોભી નહીં જાય પણ તે વૃક્ષની પાસે જશે. (પ્રસંગ 1 લો )',
          'દરેક વૈષ્ણવના મનમાં શ્રી યમુનાજી સ્વામિનીજી છે. એવો ભાવ રહેવો જોઈએ. એ યમુનાજી દ્વારા ભગવદીયની મુકુન્દમાં રતિ થાય છે. श्रीयमुनस्त्रोत्र માં શ્રી મદ વલ્લભાઆચાર્યજી એ કહ્યું છે. मुकुन्दरतिवधिनि जयति पदबंधो: सुता ( પ્રસંગ 4 થો )',
          'પ્રભુના જે ભક્તને સ્વ લીલાનું પાન કરાવડાવવું છે તેની સાથે અનેક પ્રકારની લીલાઓ કરે છે. એ ભક્તને આનંદનું દાન કરવા પોતે પણ ગૌણ રીતે લીલાઓ કરે છે. આમાં શંકા રાખવી નહીં. શ્રુતિ કહે છે. रसावै सः यं लब्ध्वानन्दी भक्ति તે પ્રભુરસ સ્વરૂપ છે અને જે તેને પ્રાપ્ત કરે છે તે આનન્દી થાય છે. અને જેને એ આનંદનો અનુભવ થાય છે. તેને અનેક લીલાનો અનુભવ થાય છે. सोडश्र्नुते सर्वान्कामान्सह ब्राह्मणाश्र्चित " ને બ્રાહ્મની સાથે સર્વ કામો ભોગવે છે. આનંદનો ભોગ ભક્તને મુખ્ય રીતે થાય છે જયારે પ્રભુને ગૌણ રીતે થાય છે. માટેજ શ્રુતિ કહે છે પ્રભુની સાથે રતિ કરવી, ક્રીડા કરવી વગેરે.',
          'જેનું ચિત્ત પ્રભુમાં લાગ્યું છે, તેને કોઈપણ ભાવો અગર પદાર્થોમાં આસક્તિ રહેતી નથી. સ્ત્રી, પુત્ર, કે પુત્રી, પિતા, માતા એ સર્વનું સુખ તેને તુચ્છ લાગે છે. ફક્ત પ્રભુપ્રેમ એજ મુખ્ય અને નિત્ય છે. (જુઓ પ્રસંગ 9 )',
          'ગુરૂના ઘરની અણપ્રસાદી લેવાથી હાનિ થાય છે.',
          'પ્રભુને પ્રસન્ન કરવાને રાગ, તાલ સ્વર વગરનું ગાન કરવાથી કાંઈ પણ ]અર્થ સરતો નથી. રાગ તાલથી હૃદયનો ભાવ બાહિર પ્રકટ થાય છે, અને ભાવ સહિત ગાન થવાથી પ્રભુ પ્રસન્ન થાય છે. (પ્રસંગ 13 )',
          'ભગવદીય સર્વદા નિર્ભય રહેવું અને પોતાનો ટેક છોડવો નહીં.',
          'ભક્ત ભાવથી પ્રભુ એટલા બધા તેના તરફ હળી જાય છે. ને તેની પ્રસન્ન મેળવવા પ્રભુ ઈતેજાર હોય છે. ( પ્રસંગ 19 )',
        ],
        notes: [
          'અમારા તરફથી પ્રગટ થયેલા વિવિધ ધોળ તથા પદ સંગ્રહ ભા. રજામાં અષ્ટાસખાના ધોળમાં નીચે પ્રમાણે ગોવિંદદાસજી નું ધોળ આપવામાં આવ્યું છે.',
          'ગોવિંદસ્વામી સદા સખા શ્રીનાથના, લીલા માંહે સુદામા સુખસારજો.\nયુગલ સ્વરૂપે ગુણ ગાન કરે હુલ્લાસમાં, ત્યાંહા પણ પ્રભુ સાંભળતા રહી પાસે જો.\nવલતી આવી વિપ્રકુળમાં જન્મીયા, સ્વામી થઈને સેવક કર્યા નીર્ધાર જો.\nપણ નિજ દર્શનની આરતી મનમાં રહે ઘણી, ગાતા કીર્તન પોતે ફરીને સાર જો.\nપછી વૈષ્ણવજન સાથે થઈને શરણ થયા, ગોસ્વામી શ્રી વિઠ્ઠલ વર ભૂપ જો.\nત્યારે દાસ થઈને મૂક્યું સ્વામી પણું, ગાનકાળમાં ચિત્ત ચોટ્યું કરી વાસજો.\nથોડો કરીને ચઢતા શ્રી ગોવર્ધનનાથજી, એ સુખ કહીન શકે વલ્લભદાસજો.',
          'ગોવિંદદાસના સેવ્ય શ્રી ઠાકોરજી શ્રી બાલકૃષ્ણજી હતા તે હાલમાં મુંબઈ માં શ્રી દ્વારકેશલાલજીને શ્રીમસ્તક બિરાજે છે.',
        ],
      ),
      VartaSection(
        title: 'ગોવિંદદાસનાં બહેન કાન્હબાઈ હતાં તેમની વાર્તા',
        prasangs: [
          VartaPrasang(
            number: 1,
            paragraphs: [
              'આ કાન્હબાઈ શ્રી નવનિતપ્રિયજીનું સ્વરૂપ પધરાવીને સેવા કરતા હતા. અને શ્રીઠાકોરજી એમને અનુભવ કરાવતા હતા. હસતા બોલતા અને ચાહે તો માંગી લેતા. એ કાન્હબાઈ જે દિવસે શ્રી ગુસાંઇજીને ઘરે સેવામાં જતા તે દિવસે રસોઈ નહોતા કરતા. ત્યારે પાતળ લાવીને ભોગ ધરતાં. ને કાંઈક સામગ્રી ઘરમાં કરી રાખતા. શ્રીઠાકોરજી બાળકની માફક જે માંગતા તે એ આપતાં.',
            ],
          ),
          VartaPrasang(
            number: 2,
            paragraphs: [
              'એક દિવસ કાન્હબાઈ શ્રી ઠાકોરજીને દેવકાબેટીજી પાસે પધરાવીને મહાવન ગયા હતા. ત્યારે રાત્રે આવી શક્યાં ન હોતા. દેવકાબેટીજીએ પોતાના શ્રી ઠાકોરજીને પોઢાડયાં પણ કાન્હબાઈના શ્રી ઠાકોરજીને પોઢવાનું ભૂલી ગયા તેથી કાન્હબાઈને શ્રી ઠાકોરજીએ જણાવ્યું કે દેવકાબેટીજી મને પોઢાડવાનું ભૂલી ગયા છે. અને હું સિંહાસન ઉપર એકલો બેસીને ડરૂ છું. આથી કાન્હબાઈ રાત્રે ત્યાંથી ચાલ્યાં અને શ્રી ગોકુળમાં આવીને દેવકાબેટીજીને જગાડ્યાં અને પોતાનાં શ્રી ઠાકોરજીને પધરાવીને ઘરે લઈ જઈને પોઢાડયાં.',
            ],
          ),
          VartaPrasang(
            number: 3,
            paragraphs: [
              'એક દિવસે કાન્હબાઈને શ્રી ગોકુલચંદ્રમાંજી એ કહ્યું. "મારી શૈય્યામાં કંઈક ખૂંચે છે." તેથી કાન્હબાઈએ જઈને નારાયણદાસ બ્રહ્મચારીને કહ્યું " શ્રી ઠાકોરજીને શૈય્યામાં ખુંચે છે. નારાયણદાસે શૈય્યાની ગાદી ખુલ્લી કરી તો રૂ માંથી વનોરા નીકળ્યાં. એ દિવસથી જયારે નારાયણદાસ બ્રહ્મચારી શૈય્યાની ગાદી અથવા રજાઈ નવી ભરાવતાં ત્યારે પોતાના હાથથી રૂ ના પોલ જોઈને ધરતા. એ કાન્હબાઈ એવાં કૃપાપાત્ર ભગવદીય હતાં.',
            ],
          ),
          VartaPrasang(
            number: 4,
            paragraphs: [
              'એક દિવસ કાન્હબાઈ શ્રીગુસાંઇજીના ધેર શ્રી નવનીતપ્રિયજીનાં દર્શન કરવાને ગયા. જઈને જુએ છે તો શ્રી નવનીતપ્રિયજી એકલા ઝૂલતા હતા. શ્રીનવનીતપ્રિયજી એ કહ્યું કાન્હબાઈ મને તું ઝુલાવ. ત્યારે કાન્હબાઈ ઝુલાવવા બેઠાં. એટલામાં જયારે શ્રી ગિરિધરજી પધાર્યા ત્યારે કાન્હબાઈએ ખીજવાઈને કહ્યું " તમે શા માટે શ્રી ઠાકોરજીને એકલા રાખ્યા? " શ્રી ગિરિધરજીએ કહ્યું " હવે કોઈ દિવસ એમ નહીં કરૂ." એ કાન્હબાઈ એવાં કૃપાપાત્ર ભગવદીય હતા.',
            ],
          ),
          VartaPrasang(
            number: 5,
            paragraphs: [
              'એક દિવસે શ્રી ગિરિધરજીને શ્રી ગોકુળનાથજીએ વિનંતી કરી પૂછ્યું કે "અમારી યજ્ઞ કરવાની ઈચ્છા છે. " ત્યારે કાન્હબાઈ બોલ્યાં " યજ્ઞરૂપ શ્રી ગોવર્ધનધર તમારે માથે બિરાજે છે. એમની સેવાથી સર્વ યજ્ઞ બની જાશે. " એ સાંભળીને શ્રી ગોકુલનાથજીએ યજ્ઞ કરવાનો વિચાર માંડી વાળ્યો. એ કાન્હબાઈની સર્વ બાળકો એવી કાની રાખતા. આ કાન્હબાઈ એવા પરમકૃપાપાત્ર ભગવદીય હતા તેથી તેમની વાર્તા કેટલીક લખીએ.',
            ],
          ),
        ],
        saar: [
          'પ્રસંગ આવે તો પણ શ્રી ઠાકોરજીને બીજાને ત્યાં નહીં પધરાવવા કારણ કે સેવા કરવામાં જો બીજાની ચૂક પડે તો શ્રી ઠાકોરજીને શ્રમ પડે',
